"""Run the exact protected original resultChart function against synthetic groups."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';source=(r/'docs/replica/source/original.js').read_text().splitlines();definitions='\n'.join(line for line in source if line.startswith(('const icons=','const icon=','const categoryDefs=','const t=','const catName=','function resultChart()')))
base=[dict(key=k,total=t,equal=e,different=d,status='completed')for k,t,e,d in [('data',12,11,1),('schema',18,17,1),('access',8,5,1),('objects',12,12,0)]];cases=[]
for lang in ['ko','en']:
 for compact in [False,True]:
  for width in [610,858,980,1060]:cases.append(dict(lang=lang,compact=compact,width=width,groups=base))
  for groups in [[dict(key='data',total=12,equal=0,different=7,status='interrupted')],[dict(key='access',total=8,equal=0,different=0,status='unstarted'),dict(key='objects',total=0,equal=0,different=0,status='completed')],[dict(key='trial',total=4,equal=3,different=1,status='completed')],[]]:cases.append(dict(lang=lang,compact=compact,width=610,groups=groups))
for number in [0,1,5,6,20,21]:cases.append(dict(lang='ko',compact=False,width=980,groups=[dict(key='data',total=number,equal=number,different=0,status='completed')]))
for i,c in enumerate(cases):c['id']=str(i)
css=(r/'docs/replica/source/original.css').read_text();(o/'resultchart-original.css').write_text(css)
html='''<!doctype html><meta charset="utf-8"><title>ResultChart · original isolation</title><link rel="stylesheet" href="resultchart-original.css"><style>body{min-width:1400px}.fixture{position:absolute;left:30px}.fixture *{animation:none!important;transition:none!important}.fixture.compact .result-columns,.fixture.compact .result-row{grid-template-columns:minmax(155px,1.4fr) repeat(3,minmax(75px,1fr)) 16px;gap:16px;padding-inline:16px}.compact .result-category{gap:8px}</style><button id="result-chart-record" style="position:fixed;right:20px;top:20px">Record ResultChart</button><div id="fixtures"></div><script>let lang='ko';let state={run:{groups:[]}};'''+definitions+'\nconst cases='+json.dumps(cases,ensure_ascii=False)+''';for(const c of cases){lang=c.lang;state.run.groups=c.groups;let wrapper=document.createElement('section');wrapper.className='fixture'+(c.compact?' compact':'');wrapper.dataset.id=c.id;wrapper.style.cssText='width:'+c.width+'px;top:'+(30+Number(c.id)*620)+'px';wrapper.innerHTML=resultChart();document.getElementById('fixtures').append(wrapper)}
document.getElementById('result-chart-record').onclick=async()=>{const rows=[...document.querySelectorAll('.fixture')].map(wrapper=>{const e=wrapper.querySelector('figure');if(!e)return{id:wrapper.dataset.id,present:false};const rect=e.getBoundingClientRect(),box=x=>{let b=x.getBoundingClientRect();return{x:b.x-rect.x,y:b.y-rect.y,width:b.width,height:b.height}};return{id:wrapper.dataset.id,present:true,width:rect.width,height:rect.height,header:box(e.querySelector('.chart-heading')),heading:box(e.querySelector('h2')),help:box(e.querySelector('.chart-heading p')),unit:box(e.querySelector('.chart-unit')),columns:box(e.querySelector('.result-columns')),labels:[...e.querySelectorAll('.result-columns>span')].slice(0,4).map(box),rows:[...e.querySelectorAll('.result-row')].map(x=>({box:box(x),name:x.getAttribute('aria-label'),numbers:[...x.querySelectorAll('b')].map(b=>Number(b.textContent))})),captionBox:box(e.querySelector('.chart-caption')),caption:box(e.querySelector('.chart-caption')),unitText:e.querySelector('.chart-unit').innerText,headingText:e.querySelector('h2').textContent,helpText:e.querySelector('.chart-heading p').textContent,captionText:e.querySelector('.chart-caption').textContent}});let response=await fetch('/evidence/source-resultchart.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!response.ok)throw Error('Evidence failed');document.getElementById('result-chart-record').textContent='ResultChart recorded';};</script>'''
(o/'resultchart.html').write_text(html)
for p in [o/'resultchart-cases.json',r/'docs/replica/source/resultchart-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
p=r/'tools/WindowsControl/fixture_server.py';p.write_text(p.read_text().replace("allowed={'source-resultrow-motion.json'","allowed={'source-resultchart.json','source-resultrow-motion.json'"));print(len(cases),'exact original chart cases prepared')
